import {
	createHevyClient,
	type HevyClient,
	type HevyExecutionOptions,
} from "@hevy-mcp/hevy-client";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import { getApiKey } from "./auth.js";
import { diagnostic, EXIT } from "./errors.js";
import { readDataSource, type DataSourceReader } from "./input.js";
import { runRoutes, type CliState } from "./routes.js";
import { writeResult, type Streams } from "./output/write.js";
export interface RunCliOptions {
	argv: string[];
	env?: Record<string, string | undefined>;
	clientFactory?: (key: string) => HevyClient;
	now?: () => Date;
	readDataSource?: DataSourceReader;
	streams?: Streams;
	execution?: HevyExecutionOptions;
}

const cliCommands = new Set([
	"user",
	"workouts",
	"routines",
	"exercises",
	"folders",
	"measurements",
	"summary",
]);
const cliSubcommands = new Set([
	"list",
	"get",
	"count",
	"events",
	"search",
	"history",
	"create",
	"update",
]);

function writeCliEvent(
	streams: Streams,
	argv: string[],
	startedAt: number,
	result: {
		outcome: "success" | "failure";
		exitCode: number;
		errorCode?: string;
	},
): void {
	const command = cliCommands.has(argv[0] ?? "") ? argv[0] : undefined;
	const subcommand = cliSubcommands.has(argv[1] ?? "") ? argv[1] : undefined;
	try {
		streams.stderr(
			`${JSON.stringify({
				timestamp: new Date().toISOString(),
				level: result.outcome === "success" ? "info" : "error",
				event: "cli.command",
				outcome: result.outcome,
				exit_code: result.exitCode,
				duration_ms: Math.round(performance.now() - startedAt),
				command: command ?? "unknown",
				subcommand: subcommand ?? "unknown",
				error_code: result.errorCode ?? null,
			})}\n`,
		);
	} catch {
		// Optional CLI logging must not change the command result.
	}
}

export async function runCli(options: RunCliOptions): Promise<number> {
	const env = options.env ?? globalThis.process.env;
	const streams = options.streams ?? {
		stdout: (text) => process.stdout.write(text),
		stderr: (text) => process.stderr.write(text),
	};
	const state: CliState = {};
	const stricliProcess = {
		stdout: { write: streams.stdout },
		stderr: { write: streams.stderr },
		exitCode: undefined as number | undefined,
	};
	const context = {
		process: stricliProcess,
		state,
		now: options.now ?? (() => new Date()),
		readDataSource: options.readDataSource ?? readDataSource,
		client: undefined as HevyClient | undefined,
		operations: undefined as HevyOperations | undefined,
		execution: options.execution,
	};
	const metaCommand = options.argv.some((value) =>
		["--help", "-h", "--version", "-v"].includes(value),
	);
	const logEnabled = !metaCommand && env.HEVY_CLI_LOG === "true";
	const startedAt = performance.now();
	try {
		if (!metaCommand) {
			const key = getApiKey(env);
			const createdClient = (
				options.clientFactory ?? ((apiKey) => createHevyClient({ apiKey }))
			)(key);
			context.client = createdClient;
			context.operations = createOperations(createdClient, {
				trainingSummaryMaxWeeks: 520,
				trainingSummaryStrictPagination: true,
			});
		}
		const exitCode = await runRoutes(options.argv, context);
		if (state.error !== undefined) throw state.error;
		if (exitCode !== 0) {
			if (logEnabled)
				writeCliEvent(streams, options.argv, startedAt, {
					outcome: "failure",
					exitCode: EXIT.usage,
				});
			return EXIT.usage;
		}
		if (state.result !== undefined) {
			const json = options.argv.includes("--json");
			writeResult(state.result, json, streams);
		}
		if (logEnabled)
			writeCliEvent(streams, options.argv, startedAt, {
				outcome: "success",
				exitCode: 0,
			});
		return 0;
	} catch (error) {
		const normalizedError = error instanceof Error ? error : String(error);
		const failure = diagnostic(normalizedError);
		if (logEnabled)
			writeCliEvent(streams, options.argv, startedAt, {
				outcome: "failure",
				exitCode: failure.code,
				errorCode: failure.error_code,
			});
		if (options.argv.includes("--json")) {
			streams.stderr(`${JSON.stringify(failure)}\n`);
		} else {
			streams.stderr(`${failure.message}\n`);
		}
		return failure.code;
	}
}
import { parseWeeks } from "../arguments.js";
import { runOperation, type CommandContext } from "./context.js";

export async function executeSummary({
	args,
	operations,
	now,
	execution,
}: CommandContext): Promise<unknown> {
	const weeks = parseWeeks(args);
	const to = now();
	const from = new Date(to.getTime() - weeks * 7 * 24 * 60 * 60 * 1000);
	const result = await runOperation(
		operations.workflows?.trainingSummary,
		"workflows.trainingSummary",
		{ weeks },
		execution,
	);
	const totalVolumeKg = result.workouts.total_volume_kg ?? 0;
	return {
		weeks,
		start_date: from.toISOString(),
		end_date: to.toISOString(),
		workout_count: result.workouts.count,
		total_duration_seconds: result.workouts.total_duration_seconds,
		exercise_count: result.workouts.exercise_count,
		set_count: result.workouts.set_count,
		total_volume_kg: totalVolumeKg,
		pages_scanned: result.workflow.pagination.workouts,
		complete: true,
	};
}
import type { HevyExecutionOptions } from "@hevy-mcp/hevy-client/types";
import type { HevyOperations } from "@hevy-mcp/operations";
import { Effect } from "effect";
import { z } from "zod";
import { UsageError, type CliArgs } from "../arguments.js";
import { ApiResponseError } from "../errors.js";
import type { DataSourceReader } from "../input.js";
import { pageEnvelope, type ApiObject } from "../output/contracts.js";

export type CommandContext = {
	args: CliArgs;
	now: () => Date;
	readDataSource: DataSourceReader;
	operations: HevyOperations;
	execution?: HevyExecutionOptions;
};

export type CommandResult = Promise<unknown>;

type InputOperation<TInput, TOutput> = {
	readonly effect: (
		input: TInput,
		options?: HevyExecutionOptions,
	) => Effect.Effect<TOutput, unknown>;
};

type OptionsOperation<TOutput> = {
	readonly effect: (
		options?: HevyExecutionOptions,
	) => Effect.Effect<TOutput, unknown>;
};

export function requireOperation<T>(operation: T | undefined, id: string): T {
	if (operation === undefined)
		throw new ApiResponseError(`Operation ${id} is not configured`);
	return operation;
}

export function collapse<T>(effect: Effect.Effect<T, unknown>): Promise<T> {
	return Effect.runPromise(effect);
}

export function runOperation<TInput, TOutput>(
	operation: InputOperation<TInput, TOutput> | undefined,
	id: string,
	input: TInput,
	execution: HevyExecutionOptions | undefined,
): Promise<TOutput> {
	const resolved = requireOperation(operation, id);
	return collapse(resolved.effect(input, execution));
}

export function runOperationWithoutInput<TOutput>(
	operation: OptionsOperation<TOutput> | undefined,
	id: string,
	execution: HevyExecutionOptions | undefined,
): Promise<TOutput> {
	const resolved = requireOperation(operation, id);
	return collapse(resolved.effect(execution));
}

export function list(
	data: ApiObject,
	source: string,
	output: string,
	page: number,
): ApiObject {
	const count = z.number().safeParse(data.page_count).data;
	const items = Array.isArray(data[source]) ? data[source] : [];
	if (
		count === undefined ||
		!Number.isSafeInteger(count) ||
		count < 0 ||
		(count === 0 && items.length > 0) ||
		(data.page !== undefined && data.page !== page)
	)
		throw new ApiResponseError("The API returned invalid pagination metadata");
	if (count > 0 && page > count)
		throw new UsageError("Requested page exceeds the API page count");
	return pageEnvelope(data, output, items);
}

export function mutationData(args: CliArgs): string {
	const parsed = z.string().safeParse(args.options.data);
	if (!parsed.success) throw new UsageError("--data is required");
	return parsed.data;
}
