			};
		if (status !== undefined)
			return {
				code: EXIT.api,
				message: `Hevy API request failed (HTTP ${status})`,
				...executionFields(error),
			};
		return {
			code: EXIT.network,
			message:
				("code" in error ? error.code : undefined) === "ETIMEDOUT"
					? "Hevy API request timed out"
					: "Unable to reach the Hevy API",
			...executionFields(error),
		};
	}
	if (error instanceof UsageError)
		return {
			code: EXIT.usage,
			message: error.message.replace(/https?:\/\/\S+/gi, "[redacted]"),
		};
	return { code: EXIT.usage, message: "Command failed" };
}
// Bug-hunt repro tests: each test asserts the documented/contracted behavior
// and fails on current code. Fake credentials and mocked fetch only.
import { createHevyClient } from "@hevy-mcp/hevy-client";
import { afterEach, describe, expect, it, vi } from "vitest";
import { runCli } from "./main.js";

const FAKE_KEY = "00000000-0000-4000-8000-000000000000";

type Responder = (request: Request, attempt: number) => Response;

async function run(
	argv: string[],
	respond: Responder,
	options: {
		env?: Record<string, string>;
		execution?: { signal?: AbortSignal; deadline?: number };
	} = {},
) {
	let out = "";
	let err = "";
	const calls: string[] = [];
	let attempt = 0;
	const fakeFetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
		const request = new Request(input, init);
		const url = new URL(request.url);
		calls.push(`${request.method} ${url.pathname}`);
		return respond(request, attempt++);
	}) as typeof fetch;
	const code = await runCli({
		argv,
		env: options.env ?? { HEVY_API_KEY: FAKE_KEY },
		execution: options.execution,
		streams: {
			stdout: (text) => {
				out += text;
			},
			stderr: (text) => {
				err += text;
			},
		},
		clientFactory: (apiKey) =>
			createHevyClient({
				apiKey,
				fetch: fakeFetch,
				sleep: async () => {},
			}),
	});
	return { code, out, err, calls };
}

const json = (body: unknown, status = 200) =>
	new Response(JSON.stringify(body), {
		status,
		headers: { "content-type": "application/json" },
	});

afterEach(() => {
	vi.useRealTimers();
});

describe("CLI bug hunt", () => {
	it("honors --json=true, which Stricli accepts as the --json flag", async () => {
		const result = await run(["workouts", "list", "--json=true"], () =>
			json({ page: 1, page_count: 1, workouts: [] }),
		);

		expect(result.code).toBe(0);
		// README: "Add --json to any command for machine-readable output."
		expect(result.out).toBe('{"page":1,"page_count":1,"workouts":[]}\n');
	});

	it("does not leak the internal expected404Outcome field from workouts get", async () => {
		const result = await run(["workouts", "get", "missing-id", "--json"], () =>
			json({ error: "Workout not found" }, 404),
		);

		// The other get commands strip operation internals; workouts get passes
		// the raw camelCase operation output straight to stdout.
		expect(result.out).not.toContain("expected404Outcome");
	});

	it.each([
		["workouts", "get", "missing-id"],
		["routines", "get", "missing-id"],
		["exercises", "get", "missing-id"],
		["measurements", "get", "2026-01-01"],
	])(
		"reports a missing resource from `%s %s` as an API failure (exit 3)",
		async (...argv) => {
			const result = await run([...argv, "--json"], () =>
				json({ error: "not found" }, 404),
			);

			// main.test.ts expects NotFoundError on /v1/workouts/:workoutId to map
			// to exit 3, and `exercises history` 404 already exits 3.
			expect({ code: result.code, out: result.out }).toEqual({
				code: 3,
				out: "",
			});
		},
	);

	it("prints help for a bare `hevy` or route-map invocation without credentials", async () => {
		for (const argv of [[], ["workouts"]]) {
			const result = await run(argv, () => json({}), { env: {} });
			// Route maps use defaultForRouteMap help; help is credential-free.
			expect({ argv, code: result.code, err: result.err }).toEqual({
				argv,
				code: 0,
				err: "",
			});
		}
	});

	it("does not describe user cancellation as an unreachable API", async () => {
		const result = await run(["user", "--json"], () => json({}), {
			execution: {
				signal: AbortSignal.abort(
					new DOMException("CLI shutdown requested by SIGINT", "AbortError"),
				),
			},
		});
		const failure = JSON.parse(result.err) as { message: string };

		expect(result.calls).toEqual([]);
		expect(failure.message).not.toBe("Unable to reach the Hevy API");
	});

	it("reports the CLI command deadline as a timeout", async () => {
		const result = await run(["user", "--json"], () => json({}), {
			execution: { deadline: Date.now() - 1 },
		});
		const failure = JSON.parse(result.err) as { message: string };

		expect(failure.message).toBe("Hevy API request timed out");
	});

	it("does not report a created folder as success when the response has no folder", async () => {
		const result = await run(
			[
				"folders",
				"create",
				"--data",
				'{"routine_folder":{"title":"Strength"}}',
				"--yes",
				"--json",
			],
			() => new Response("<html>gateway</html>", { status: 200 }),
		);

		expect(result.calls).toEqual(["POST /v1/routine_folders"]);
		// The command contract returns { routine_folder: RoutineFolder }.
		expect({ code: result.code, out: result.out }).not.toEqual({
			code: 0,
			out: "{}\n",
		});
	});

	it("reports a summary window that contains every workout it counted", async () => {
		vi.useFakeTimers({ toFake: ["Date"] });
		vi.setSystemTime(new Date("2026-11-06T15:00:00.000Z"));
		const workoutStart = "2026-10-30T08:00:00Z";
		const result = await run(["summary", "--weeks", "1", "--json"], (request) =>
			new URL(request.url).pathname === "/v1/workouts"
				? json({
						page: 1,
						page_count: 1,
						workouts: [
							{
								id: "w1",
								title: "Morning",
								description: null,
								start_time: workoutStart,
								end_time: "2026-10-30T09:00:00Z",
								updated_at: "2026-10-30T09:00:00Z",
								created_at: "2026-10-30T09:00:00Z",
								exercises: [],
							},
						],
					})
				: json({ page: 1, page_count: 1, body_measurements: [] }),
		);
		const summary = JSON.parse(result.out) as {
			start_date: string;
			end_date: string;
			workout_count: number;
		};

		expect(summary.workout_count).toBe(1);
		// The counted workout must fall inside the reported window.
		expect(summary.start_date).toBe("2026-10-30T00:00:00.000Z");
	});
});

