		safe_to_retry: fields.safeToRetry ?? false,
	};
	const errorCode =
		fields.code !== undefined && SAFE_ERROR_CODES.has(fields.code)
			? fields.code
			: undefined;
	return errorCode === undefined
		? execution
		: { ...execution, error_code: errorCode };
}

